import frappe
from frappe.model.document import Document

class StockMovement(Document):
	def validate(self):
		self.calculate_new_stock()

	def calculate_new_stock(self):
		self.previous_stock = self.current_stock or 0
		if self.movement_type in ["Receipt", "Return"]:
			self.new_stock = self.previous_stock + self.quantity
		elif self.movement_type in ["Issue", "Expired"]:
			self.new_stock = self.previous_stock - self.quantity
		elif self.movement_type == "Adjustment":
			self.new_stock = self.quantity

	def on_submit(self):
		# Update medication stock
		medication = frappe.get_doc("Medication", self.medication)
		medication.current_stock = self.new_stock
		medication.save()
EOF

